/* @lc app=leetcode id=2448 lang=kotlin */ class Solution { fun minCost(nums: IntArray, cost: IntArray): Long = nums.indices.sortedBy { nums[it] }.let { o -> cost.sumOf { it.toLong() }.let { tot -> o.runningFold(0L) { s, i -> s + cost[i] }.drop(1).indexOfFirst { it * 2 >= tot }.let { k -> nums[o[k]].let { m -> nums.indices.sumOf { Math.abs(nums[it] - m).toLong() * cost[it] } } } } } }